catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}

	var validDate = isDateInFuture(newValue);

	if (validDate){
		g_form.addErrorMessage('Invalid date, select dates less than the current day.');
		g_form.clearValue('date');
	}else {
		g_form.clearMessages();
	}

}

function parseDate(dateStr) {
    var isBRFormat = /^(\d{2})\/(\d{2})\/(\d{4})$/.test(dateStr); // Verifica se é formato BR (DD/MM/YYYY)
    var isUSAFormat = /^(\d{2})\/(\d{2})\/(\d{4})$/.test(dateStr); // Verifica se é formato USA (MM/DD/YYYY)
    var isISOFormat = /^(\d{4})-(\d{2})-(\d{2})$/.test(dateStr); // Verifica se é formato ISO (YYYY-MM-DD)
    var parts; // Declaração única de 'parts'

    if (isBRFormat) {
        parts = dateStr.split('/').map(Number);
        return new Date(parts[2], parts[1] - 1, parts[0]); // Converte para objeto Date
    } else if (isUSAFormat) {
        parts = dateStr.split('/').map(Number);
        return new Date(parts[2], parts[0] - 1, parts[1]); // Converte para objeto Date
    } else if (isISOFormat) {
        parts = dateStr.split('-').map(Number);
        return new Date(parts[0], parts[1] - 1, parts[2]); // Converte para objeto Date
    } else {
        throw new Error("Formato de data inválido. Use DD/MM/YYYY, MM/DD/YYYY ou YYYY-MM-DD.");
    }
}

// Função para verificar se a data é maior que hoje
function isDateInFuture(dateStr) {
    try {
        var date = parseDate(dateStr);
        var today = new Date();
        today.setHours(0, 0, 0, 0); // Zera as horas para considerar apenas a data

        return date > today;
    } catch (error) {
        return null; // Retorna null em caso de erro
    }
}
